INSERT INTO bylaws_version (slug, title, version_label, effective_date, revision_history, blocks, updated_at) VALUES
('2026-amendment', 'RUN 회칙', '현행 (2026년 개정)', '2026-08-07', '[{"date":"2017. 03. 18.","label":"제정"},{"date":"2026. 08. 07.","label":"일부개정"}]', '[{"type":"chapter","text":"총칙"},{"type":"article","text":"명칭"},{"type":"body","text":"본회는 한국과학기술원(이하 본교) 알고리즘 문제 해결 동아리 RUN(런)이라 한다."},{"type":"article","text":"정의 및 목적"},{"type":"body","text":"본회는 알고리즘 문제 해결에 관한 지식을 축적, 공유하고 그 지식을 통해 개인의 실력 향상과 대학 문화의 발전에 기여함을 목적으로 한다."},{"type":"article","text":"소속 및 소재"},{"type":"body","text":"본 회는 KAIST 학부 동아리연합회의 소속으로 본 회의 동아리 방은 가능한 한 KAIST 내에 둔다."},{"type":"chapter","text":"회원"},{"type":"article","text":"구성"},{"type":"body","text":"본 회의 회원은 정회원과 명예회원으로 구성한다."},{"type":"article","text":"자격"},{"type":"clause","text":"본 회의 정회원은 본교 학부 총학생회 회원 또는 대학원 총학생회 회원에 한한다."},{"type":"clause","text":"정회원으로서 본교를 졸업한 자 또는 본회 회원의 추천을 받아 본회 임원의 동의를 얻은 자는 본회의 명예회원이 될 수 있다."},{"type":"article","text":"권리"},{"type":"body","text":"정회원은 본회의 모든 활동에 참여할 수 있고, 의견을 발의할 수 있다. 명예회원은 본회의 모든 활동을 참관할 수 있다."},{"type":"article","text":"의무"},{"type":"body","text":"정회원은 본회가 결정하는 사항과 회칙을 준수하고 회비를 납부할 의무를 가진다."},{"type":"article","text":"가입과 탈퇴"},{"type":"clause","text":"본회의 정회원이 되기 위해서는 정기 회원 모집 또는 본회 회원의 추천을 통해 입회를 지원한 뒤 임원진의 동의를 얻어야 한다."},{"type":"clause","text":"본회의 정회원은 휴학 등의 사유가 있을 경우 임원진의 동의를 얻어 일정기간 회원 자격을 반납한 후 재취득할 수 있다."},{"type":"clause","text":"본회에 탈퇴의사를 표시한 자는 본회의 회원 자격을 포기한 것으로 간주한다."},{"type":"clause","text":"본회에서 탈퇴한 자로서 본회 회원의 추천을 받아 본회 임원들의 동의를 얻으면 본회의 회원자격을 다시 얻을 수 있다."},{"type":"clause","text":"회원은 다음 각 호에 해당하는 경우 임원진 과반수의 찬성 또는 총회 의결을 거쳐 제적될 수 있다. <개정 2026. 08. 07.>"},{"type":"item","text":"회비 미납"},{"type":"item","text":"본회 내 분란 야기"},{"type":"item","text":"동아리의 명예 실추 <개정 2026. 08. 07.>"},{"type":"chapter","text":"동아리 총회"},{"type":"article","text":"지위"},{"type":"body","text":"동아리 총회(이하 총회)는 본회의 최고 심의, 의결기구이다."},{"type":"article","text":"권한"},{"type":"body","text":"총회는 본회의 존립 및 회원 전체에 대한 모든 중대한 사항을 결정한다."},{"type":"article","text":"구성"},{"type":"body","text":"총회는 본회에 등록된 모든 회원으로 구성한다."},{"type":"article","text":"의장"},{"type":"body","text":"총회의 의장은 본회 회장이 맡는다."},{"type":"article","text":"소집"},{"type":"clause","text":"총회는 각 호에 해당하는 경우 본회 회장이 소집한다."},{"type":"item","text":"본회 정회원의 1/4 이상에 의한 요구 시"},{"type":"item","text":"긴급을 요하는 경우 본회 회장이 판단 하"},{"type":"clause","text":"총회는 재적 인원의 1/3 이상의 재석과 회장의 참석으로 성립한다. 단, 회장 또는 임원이 탄핵 및 징계의 대상인 경우 회장의 참석이나 소집 없이도 총회가 성립하며, 부회장 또는 참석 정회원 중에서 선출된 임시의장이 회장의 소집 및 의장 권한을 대행한다. <개정 2026. 08. 07.>"},{"type":"clause","text":"총회 소집 시 최소 7일 전에 모든 회원에게 안건을 공고하여야 한다. <신설 2026. 08. 07.>"},{"type":"clause","text":"총회는 대면을 원칙으로 하되, 디스코드 등 실시간 소통이 가능한 온라인 매체를 통해서도 진행할 수 있으며 온라인 참석자도 재석으로 인정한다. <신설 2026. 08. 07.>"},{"type":"article","text":"의결"},{"type":"clause","text":"재적 인원 1/3 이상의 재석과 기권을 제외한 재석 인원의 과반수의 찬성으로 의결한다. <개정 2026. 08. 07.>"},{"type":"clause","text":"기권 표수가 재석 인원의 1/5 이상인 경우 또는 가부동수인 경우 재투표를 실시하여 재차 동일한 경우 부결된 것으로 한다. <개정 2026. 08. 07.>"},{"type":"chapter","text":"임원"},{"type":"article","text":"구성"},{"type":"clause","text":"본 회의 원활한 운영을 위하여 회장, 부회장, 총무로 임원진을 구성한다."},{"type":"clause","text":"필요에 따라 회장 또는 부회장이 총무직을 겸임할 수 있다. <신설 2026. 08. 07.>"},{"type":"clause","text":"필요에 따라 임원진의 의결을 거쳐 추가적인 임원을 둘 수 있다. <신설 2026. 08. 07.>"},{"type":"article","text":"지위 및 역할"},{"type":"clause","text":"회장은 본회를 대표하며, 총회의 의장이 된다."},{"type":"clause","text":"총무는 금전과 관련된 모든 업무를 총괄 및 집행한다."},{"type":"clause","text":"회장은 임기만료, 자진사퇴, 또는 총회의 탄핵 의결에 의하지 않고는 그 직을 상실하지 않는다. <개정 2026. 08. 07.>"},{"type":"clause","text":"회장이 자진사퇴하고자 할 경우 최소 2개월 전에 모든 임원에게 그 의사를 통지하고, 업무 및 자료의 인수인계를 마친 후 사퇴한다. 다만 부득이한 사유로 사전 통지가 불가능한 경우 그 사유를 소명하여야 한다. <신설 2026. 08. 07.>"},{"type":"clause","text":"본회 회장 유고 또는 궐위 시 부회장이 업무 및 권한을 대행하며, 부회장의 권한을 대행할 사람을 총회에서 선출한다."},{"type":"clause","text":"본회 부회장 유고 또는 궐위 시 본회의 정회원을 대상으로 공고하여 부회장의 권한을 대행할 사람을 총회에서 선출한다."},{"type":"clause","text":"임원의 임기는 한 학기(6개월)로 하며, 연임 횟수에 제한을 두지 아니한다. 단, KAIST 학부 동아리연합회 자격(대표자 임기 및 신분 요건)을 유지하기 위하여, 회장직의 통산 임기는 최대 3학기(1년 6개월)를 초과할 수 없으며 대표자는 학부 총학생회 정회원이어야 한다. <신설 2026. 08. 07.>"},{"type":"clause","text":"차기 회장은 직전 회장의 추천을 받은 자 중 총회의 동의를 얻어 선출한다. 단, 직전 회장의 졸업, 군 입대, 자진 사퇴 등으로 인하여 추천권을 행사할 수 없는 비상 상황 시에는 임원진 또는 정회원 5인 이상의 추천으로 이를 갈음한다. <신설 2026. 08. 07.>"},{"type":"article","text":"권한 및 의무"},{"type":"clause","text":"회장은 대외활동에서 대표권을 가지고 활동할 수 있다."},{"type":"clause","text":"회장은 총회를 소집하고 안건을 발의할 수 있다."},{"type":"clause","text":"임원은 총회에서 회칙 개정안을 발의할 수 있다."},{"type":"clause","text":"임원은 본회의 제반 사업을 계획하고 예산안을 편성할 수 있다."},{"type":"clause","text":"임원은 본회 회원에 대한 징계안을 발의할 수 있다."},{"type":"clause","text":"총무는 각 호에 해당하는 권한 및 의무를 지닌다."},{"type":"item","text":"회비의 수납, 관리 및 지출"},{"type":"item","text":"회계장부의 기록 및 본 회의 모든 회원이 접근 가능하게 관리"},{"type":"clause","text":"회장은 총무가 예산안 편성, 회비 관리 등 재정 업무를 적정하게 수행하고 있는지 감독할 의무를 지닌다. <신설 2026. 08. 07.>"},{"type":"article","text":"임원의 탄핵"},{"type":"clause","text":"회장을 포함한 임원이 직무를 태만히 하거나 회칙을 위반한 경우, 본회 정회원 10% 이상 또는 정회원 5인 이상의 연서로 탄핵을 발의할 수 있다. <신설 2026. 08. 07.>"},{"type":"clause","text":"탄핵안은 총회에 상정되어 재석 인원 2/3 이상의 찬성으로 의결한다. <신설 2026. 08. 07.>"},{"type":"clause","text":"탄핵이 의결된 임원은 즉시 그 직을 상실하며, 궐위된 직위는 본회의 관련 규정에 따라 후임자를 선출한다. <신설 2026. 08. 07.>"},{"type":"chapter","text":"운영"},{"type":"article","text":"재정"},{"type":"clause","text":"회원으로부터 징수하는 회비 및 임시 회비, 기부금 또는 찬조금을 재원으로 하며, 학생회와 기성회의 보조, 외부의 후원을 받을 수 있다."},{"type":"clause","text":"회원은 알고리즘 문제 해결 및 동아리 관련 활동 시 본회 재정의 지원을 요청할 수 있다."},{"type":"clause","text":"정기 회비의 금액과 임시 회비의 징수는 총회에서 심의, 의결 및 공고한다."},{"type":"clause","text":"총무에 의한 예산 보고는 회원들에게 공개되어야 한다."},{"type":"clause","text":"재정의 운영은 총무의 판단 하에 이뤄지고, 회원은 이에 대한 이의를 총회를 통해 제기할 수 있다."},{"type":"article","text":"모임 및 활동"},{"type":"clause","text":"본회의 정기 모임 및 교육 목적의 모임은 동아리의 운영 상황을 고려하여 임원진의 재량에 따라 그 주기와 방식을 정하여 운영한다. <개정 2026. 08. 07.>"},{"type":"article","text":"회칙 개정"},{"type":"clause","text":"본회의 회원은 회칙의 개정을 요구할 수 있다."},{"type":"clause","text":"회칙의 개정안은 총회에 상정되어 재석 인원 2/3 이상의 찬성으로 의결하여 확정한다. <개정 2026. 08. 07.>"},{"type":"article","text":"부칙"},{"type":"clause","text":"본 회칙에 명시되어 있지 않거나 모호한 상황 중, 회원 전체에 영향을 미치는 중요 사안은 총회 안건으로 상정하여 의결하며, 그 외의 일반 사안은 회원들의 의견 수렴 후 임원진 회의의 의결에 따른다. <개정 2026. 08. 07.>"},{"type":"clause","text":"본회가 해산될 경우 잔여 재산은 총회의 의결을 거쳐 처리한다. <신설 2026. 08. 07.>"},{"type":"clause","text":"본 회칙은 2017년 3월 19일부터 유효하다."},{"type":"clause","text":"본 개정 회칙은 총회의 의결을 거쳐 공포한 날부터 유효하다. <신설 2026. 08. 07.>"}]', datetime('now')),
('2017-founding', 'RUN 회칙', '2017년 제정', '2017-03-19', '[{"date":"2017. 03. 18.","label":"제정"}]', '[{"type":"chapter","text":"총칙"},{"type":"article","text":"명칭"},{"type":"body","text":"본회는 한국과학기술원(이하 본교) 알고리즘 문제 해결 동아리 RUN(런)이라 한다."},{"type":"article","text":"정의 및 목적"},{"type":"body","text":"본회는 알고리즘 문제 해결에 관한 지식을 축적, 공유하고 그 지식을 통해 개인의 실력 향상과 대학 문화의 발전에 기여함을 목적으로 한다."},{"type":"article","text":"소속 및 소재"},{"type":"body","text":"본 회는 KAIST 학부 동아리연합회의 소속으로 본 회의 동아리 방은 가능한 한 KAIST 내에 둔다."},{"type":"chapter","text":"회원"},{"type":"article","text":"구성"},{"type":"body","text":"본 회의 회원은 정회원과 명예회원으로 구성한다."},{"type":"article","text":"자격"},{"type":"clause","text":"본 회의 정회원은 본교 학부 총학생회 회원 또는 대학원 총학생회 회원에 한한다."},{"type":"clause","text":"정회원으로서 본교를 졸업한 자 또는 본회 회원의 추천을 받아 본회 임원의 동의를 얻은 자는 본회의 명예회원이 될 수 있다."},{"type":"article","text":"권리"},{"type":"body","text":"정회원은 본회의 모든 활동에 참여할 수 있고, 의견을 발의할 수 있다. 명예회원은 본회의 모든 활동을 참관할 수 있다."},{"type":"article","text":"의무"},{"type":"body","text":"정회원은 본회가 결정하는 사항과 회칙을 준수하고 회비를 납부할 의무를 가진다."},{"type":"article","text":"가입과 탈퇴"},{"type":"clause","text":"본회의 정회원이 되기 위해서는 정기 회원 모집 또는 본회 회원의 추천을 통해 입회를 지원한 뒤 임원진의 동의를 얻어야 한다."},{"type":"clause","text":"본회의 정회원은 휴학 등의 사유가 있을 경우 임원진의 동의를 얻어 일정기간 회원 자격을 반납한 후 재취득할 수 있다."},{"type":"clause","text":"본회에 탈퇴의사를 표시한 자는 본회의 회원 자격을 포기한 것으로 간주한다."},{"type":"clause","text":"본회에서 탈퇴한 자로서 본회 회원의 추천을 받아 본회 임원들의 동의를 얻으면 본회의 회원자격을 다시 얻을 수 있다."},{"type":"clause","text":"회원은 다음 각 호에 해당하는 경우 회장의 판단 하에 제적될 수 있다."},{"type":"item","text":"회비 미납"},{"type":"item","text":"본회 내 분란 야기"},{"type":"item","text":"총회 의결을 거친 제적 요청"},{"type":"chapter","text":"동아리 총회"},{"type":"article","text":"지위"},{"type":"body","text":"동아리 총회(이하 총회)는 본회의 최고 심의, 의결기구이다."},{"type":"article","text":"권한"},{"type":"body","text":"총회는 본회의 존립 및 회원 전체에 대한 모든 중대한 사항을 결정한다."},{"type":"article","text":"구성"},{"type":"body","text":"총회는 본회에 등록된 모든 회원으로 구성한다."},{"type":"article","text":"의장"},{"type":"body","text":"총회의 의장은 본회 회장이 맡는다."},{"type":"article","text":"소집"},{"type":"clause","text":"총회는 각 호에 해당하는 경우 본회 회장이 소집한다."},{"type":"item","text":"본회 정회원의 1/4 이상에 의한 요구 시"},{"type":"item","text":"긴급을 요하는 경우 본회 회장이 판단 하"},{"type":"clause","text":"총회는 재적 인원의 1/6 이상의 재석과 회장의 참석으로 성립한다."},{"type":"article","text":"의결"},{"type":"clause","text":"재적 인원 1/6 이상의 재석과 기권을 제외한 재석 인원의 과반수의 찬성으로 의결한다."},{"type":"clause","text":"기권 표수가 재석 인원의 1/6 이상인 경우 또는 가부동수인 경우 재투표를 실시하여 재차 동일한 경우 부결된 것으로 한다."},{"type":"chapter","text":"임원"},{"type":"article","text":"구성"},{"type":"body","text":"본 회의 원활한 운영을 위하여 회장, 부회장, 총무로 임원진을 구성한다."},{"type":"article","text":"지위 및 역할"},{"type":"clause","text":"회장은 본회를 대표하며, 총회의 의장이 된다."},{"type":"clause","text":"총무는 금전과 관련된 모든 업무를 총괄 및 집행한다."},{"type":"clause","text":"회장은 임기만료나 자진사퇴에 의하지 않고는 그 직을 상실하지 않는다."},{"type":"clause","text":"본회 회장 유고 또는 궐위 시 부회장이 업무 및 권한을 대행하며, 부회장의 권한을 대행할 사람을 총회에서 선출한다."},{"type":"clause","text":"본회 부회장 유고 또는 궐위 시 본회의 정회원을 대상으로 공고하여 부회장의 권한을 대행할 사람을 총회에서 선출한다."},{"type":"article","text":"권한 및 의무"},{"type":"clause","text":"회장은 대외활동에서 대표권을 가지고 활동할 수 있다."},{"type":"clause","text":"회장은 총회를 소집하고 안건을 발의할 수 있다."},{"type":"clause","text":"임원은 총회에서 회칙 개정안을 발의할 수 있다."},{"type":"clause","text":"임원은 본회의 제반 사업을 계획하고 예산안을 편성할 수 있다."},{"type":"clause","text":"임원은 본회 회원에 대한 징계안을 발의할 수 있다."},{"type":"clause","text":"총무는 각 호에 해당하는 권한 및 의무를 지닌다."},{"type":"item","text":"회비의 수납, 관리 및 지출"},{"type":"item","text":"회계장부의 기록 및 본 회의 모든 회원이 접근 가능하게 관리"},{"type":"chapter","text":"운영"},{"type":"article","text":"재정"},{"type":"clause","text":"회원으로부터 징수하는 회비 및 임시 회비, 기부금 또는 찬조금을 재원으로 하며, 학생회와 기성회의 보조, 외부의 후원을 받을 수 있다."},{"type":"clause","text":"회원은 알고리즘 문제 해결 및 동아리 관련 활동 시 본회 재정의 지원을 요청할 수 있다."},{"type":"clause","text":"정기 회비의 금액과 임시 회비의 징수는 총회에서 심의, 의결 및 공고한다."},{"type":"clause","text":"총무에 의한 예산 보고는 회원들에게 공개되어야 한다."},{"type":"clause","text":"재정의 운영은 총무의 판단 하에 이뤄지고, 회원은 이에 대한 이의를 총회를 통해 제기할 수 있다."},{"type":"article","text":"모임 및 활동"},{"type":"clause","text":"주 1회 이상 정기 모임을 가진다. 단, 시험 기간은 예외로 한다."},{"type":"clause","text":"월 1회 이상 교육 목적의 정기 모임을 가진다. 단, 시험 기간은 예외로 한다."},{"type":"article","text":"회칙 개정"},{"type":"clause","text":"본회의 회원은 회칙의 개정을 요구할 수 있다."},{"type":"clause","text":"회칙의 개정은 총회를 통한 의견 수렴 후 회장이 진행한다."},{"type":"article","text":"부칙"},{"type":"clause","text":"본 회칙에 명시되어 있지 않거나 모호한 상황은 회원들의 의견 수렴 후 회장의 판단에 따른다."},{"type":"clause","text":"본 회칙은 2017년 3월 19일부터 유효하다."}]', datetime('now'))
